application.css:
* { box-sizing: border-box; }

:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #202538;
  background: #f4f6fb;
}

body {
  margin: 0;
  min-height: 100vh;
  background: radial-gradient(circle at 15% 5%, #e7edff 0, transparent 32%), #f4f6fb;
}

.app-shell {
  width: min(100% - 32px, 680px);
  margin: 0 auto;
  padding: 7vh 0 30px;
}

.todo-card {
  background: rgba(255, 255, 255, .94);
  border: 1px solid #e7eaf2;
  border-radius: 24px;
  padding: clamp(24px, 5vw, 42px);
  box-shadow: 0 18px 55px rgba(48, 57, 88, .1);
}

.app-header { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 30px; }
.eyebrow { margin: 0 0 7px; color: #6874cf; font-size: .74rem; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(2rem, 6vw, 2.8rem); letter-spacing: -.055em; line-height: 1; }
.subtitle { color: #8990a5; margin: 12px 0 0; font-size: .95rem; }
.header-mark { display: grid; place-items: center; width: 48px; height: 48px; border-radius: 15px; color: #fff; background: linear-gradient(135deg, #7885df, #5665c8); font-size: 1.5rem; box-shadow: 0 9px 20px rgba(94, 108, 207, .27); }

.task-form { display: flex; gap: 10px; margin-bottom: 34px; }
.task-form input { min-width: 0; flex: 1; border: 1px solid #e1e4ee; border-radius: 12px; padding: 14px 16px; color: #252a3b; background: #fafbfe; font: inherit; outline: none; transition: .2s; }
.task-form input:focus { border-color: #7784dc; box-shadow: 0 0 0 4px rgba(119, 132, 220, .13); background: #fff; }
.task-form button { border: 0; border-radius: 12px; padding: 0 20px; color: #fff; background: #5968ca; font: inherit; font-weight: 700; cursor: pointer; transition: .2s; }
.task-form button:hover { background: #4656b8; transform: translateY(-1px); }
.task-form button:active { transform: translateY(0); }

.list-heading { display: flex; align-items: center; justify-content: space-between; padding-bottom: 12px; border-bottom: 1px solid #edf0f5; }
.list-heading h2 { margin: 0; font-size: 1rem; }
.count { color: #969caf; font-size: .82rem; }
.count strong { color: #5968ca; }
.task-list { display: flex; flex-direction: column; }
.task-item { display: flex; align-items: center; gap: 13px; min-height: 65px; border-bottom: 1px solid #edf0f5; animation: appear .2s ease-out; }
.task-item:last-child { border-bottom: 0; }
.complete-control { appearance: none; width: 21px; height: 21px; flex: 0 0 21px; border: 2px solid #cbd0df; border-radius: 50%; cursor: pointer; position: relative; transition: .2s; }
.complete-control:hover { border-color: #6977d2; }
.complete-control:checked { border-color: #6876d2; background: #6876d2; }
.complete-control:checked::after { content: "✓"; position: absolute; color: white; font-size: 13px; font-weight: 800; left: 3px; top: -1px; }
.task-text { flex: 1; overflow-wrap: anywhere; font-size: .96rem; }
.task-item[data-completed="true"] .task-text { color: #a1a6b5; text-decoration: line-through; }
.delete-button { border: 0; color: #b3b8c6; background: transparent; font-size: 1.25rem; line-height: 1; padding: 8px; cursor: pointer; }
.delete-button:hover { color: #e06b7a; }
.empty-state { padding: 42px 0 18px; text-align: center; color: #969caf; }
.empty-icon { display: grid; place-items: center; width: 42px; height: 42px; margin: 0 auto 14px; border-radius: 14px; color: #7885d5; background: #eef0ff; }
.empty-state p { margin: 0 0 5px; color: #626a80; font-weight: 700; }
.empty-state span { font-size: .85rem; }
.page-note { margin: 18px 0 0; color: #9ba1b3; text-align: center; font-size: .75rem; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 460px) { .task-form { flex-direction: column; } .task-form button { min-height: 46px; } }

application.javascript:
const form = document.getElementById('task-form');
const input = document.querySelector('[data-testid="task-input"]');
const list = document.querySelector('[data-testid="task-list"]');
const count = document.querySelector('[data-testid="incomplete-count"]');
const emptyState = document.getElementById('empty-state');

let tasks = [];

function render() {
  list.replaceChildren();
  tasks.forEach((task) => {
    const item = document.createElement('div');
    item.className = 'task-item';
    item.dataset.testid = 'task';
    item.dataset.completed = String(task.completed);

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.className = 'complete-control';
    checkbox.dataset.testid = 'task-complete';
    checkbox.checked = task.completed;
    checkbox.setAttribute('aria-label', `Mark ${task.text} as ${task.completed ? 'incomplete' : 'complete'}`);
    checkbox.addEventListener('change', () => {
      task.completed = checkbox.checked;
      render();
    });

    const text = document.createElement('span');
    text.className = 'task-text';
    text.dataset.testid = 'task-text';
    text.textContent = task.text;

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.dataset.testid = 'task-delete';
    remove.setAttribute('aria-label', `Delete ${task.text}`);
    remove.innerHTML = '&times;';
    remove.addEventListener('click', () => {
      tasks = tasks.filter((entry) => entry.id !== task.id);
      render();
    });

    item.append(checkbox, text, remove);
    list.append(item);
  });
  count.textContent = tasks.filter((task) => !task.completed).length;
  emptyState.hidden = tasks.length > 0;
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    input.focus();
    return;
  }
  tasks.push({ id: Date.now() + Math.random(), text, completed: false });
  input.value = '';
  render();
  input.focus();
});

render();
